import 'package:flutter/material.dart';
import '../../core/data/customer_repository.dart';
import '../../shared/irkop_ui.dart';
class CustomersPage extends StatefulWidget{const CustomersPage({super.key,this.businessId});final String? businessId;@override State<CustomersPage> createState()=>_CustomersPageState();}
class _CustomersPageState extends State<CustomersPage>{final _repo=CustomerRepository();late Future<List<Customer>> _future;String _query='';@override void initState(){super.initState();_future=_load();}Future<List<Customer>> _load()=>widget.businessId==null?Future.value(const[]):_repo.loadCustomers(widget.businessId!);Future<void> _refresh()async{setState(()=>_future=_load());await _future;}Future<void> _edit([Customer? x])async{final b=widget.businessId;if(b==null)return;final n=TextEditingController(text:x?.name??''),p=TextEditingController(text:x?.phone??'');final ok=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,builder:(c)=>Padding(padding:EdgeInsets.fromLTRB(16,16,16,MediaQuery.of(c).viewInsets.bottom+16),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(x==null?'Tambah Pelanggan':'Edit Pelanggan'),TextField(controller:n,decoration:const InputDecoration(labelText:'Nama')),TextField(controller:p,decoration:const InputDecoration(labelText:'Telepon')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Simpan'))])));if(ok==true&&n.text.trim().isNotEmpty){try{if(x==null){await _repo.createCustomer(businessId:b,name:n.text,phone:p.text);}else{await _repo.updateCustomer(id:x.id,businessId:b,name:n.text,phone:p.text);}await _refresh();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Gagal: '+e.toString())));}}n.dispose();p.dispose();}Future<void> _delete(Customer x)async{final b=widget.businessId;if(b==null)return;await _repo.deleteCustomer(id:x.id,businessId:b);await _refresh();}
@override Widget build(BuildContext context)=>FutureBuilder<List<Customer>>(future:_future,builder:(context,s){final data=(s.data??const <Customer>[]).where((c)=>c.name.toLowerCase().contains(_query.toLowerCase())||(c.phone??'').contains(_query)).toList();return RefreshIndicator(onRefresh:_refresh,child:ListView(padding:const EdgeInsets.all(16),children:[IrkopSectionHeader(eyebrow:'Pelanggan',title:'Data Pelanggan',subtitle:'Tambah, edit dan kelola pelanggan.',icon:Icons.people_outline,action:'Tambah',onAction:()=>_edit()),const SizedBox(height:14),TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari pelanggan atau nomor',border:OutlineInputBorder()),onChanged:(v)=>setState(()=>_query=v)),const SizedBox(height:12),if(s.connectionState!=ConnectionState.done)const Center(child:Padding(padding:EdgeInsets.all(32),child:CircularProgressIndicator())),if(s.hasError)Text('Gagal memuat: '+s.error.toString()),if(s.connectionState==ConnectionState.done&&!s.hasError&&data.isEmpty)const EmptyStateCard(icon:Icons.people_outline,title:'Belum ada pelanggan',subtitle:'Tambahkan pelanggan baru.'),...data.map((c)=>Card(child:ListTile(leading:CircleAvatar(child:Text(c.name.isEmpty?'P':c.name[0].toUpperCase())),title:Text(c.name),subtitle:Text((c.phone??'').isEmpty?'Tanpa nomor telepon':c.phone!),trailing:Wrap(children:[IconButton(icon:const Icon(Icons.edit_outlined),onPressed:()=>_edit(c)),IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>_delete(c))]))))]));});}